using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class CreatureTimberChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var s=new SliceState();s.Hybrid.time=10;s.timberRelay=new TimberRelayMemory{count=1,cutter=2,carrier=-1,creature=true,source="tree",amount=3,time=10};Check(s.Valid()&&JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(s)).Valid(),"Creature relay invalid");var page=CreationBookText.Read(s,CreationBookSection.Provisions,1);Check(page.text.Contains("The creature carried")&&!page.text.Contains("Both remember"),"Creature haul shown as villager cooperation");s.timberRelay.creature=false;Check(!s.Valid(),"Negative villager carrier accepted");Debug.Log("BWVR_CREATURE_TIMBER_MODEL_PASS: source-specific saved carrier and Book attribution");}
 public static void VerifyRuntime(){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var world=slice.GetComponentInChildren<VillageResources>();var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var nav=world.Navigation;Check(!nav.TreeNavigationPending,"Wait for navigation");var stateField=typeof(QuestSlice).GetField("state",F);var original=(SliceState)stateField.GetValue(slice);var actors=world.Gatherers;var worker=actors[2];var positions=actors.Select(a=>a.transform.position).ToArray();var rotations=actors.Select(a=>a.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var ideas=god.Targets.Where(t=>t.GetComponent<ConstructionInspiration>()!=null).ToArray();var active=ideas.Select(t=>t.gameObject.activeSelf).ToArray();SliceState test=null;GameObject blocker=null;
  void StageGod(){bool found=false;for(int i=0;i<24;i++){var wanted=worker.transform.position+Quaternion.Euler(0,i*15,0)*Vector3.forward*nav.Scale*18;if(!god.GetComponent<IslandNavigator>().CanPlace(wanted,out var at))continue;god.transform.position=at;god.transform.LookAt(new Vector3(worker.transform.position.x,at.y,worker.transform.position.z));god.GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();if(god.CanSeeCue(worker.GetComponent<HybridTarget>(),false,true)&&worker.TimberApproach(god,out _)&&god.CanReach(world.StoreApproach)){found=true;break;}}Check(found,"No visible creature approach");}
  void Harvest(){god.Interrupt("Creature timber fixture");foreach(var a in cooldowns.Keys)a.cooldown=100000;worker.Cancel();foreach(var a in actors)a.transform.position=world.StoreApproach+Vector3.up*nav.Scale*600;Check(worker.GetComponent<IslandNavigator>().CanPlace(world.StoreApproach,out var at),"No worker stage");worker.transform.position=at;worker.GetComponent<IslandNavigator>().ResetRoute();var source=world.sources.Where(s=>s.kind==VillageResource.Wood&&!world.State.Find(s.id).felled&&world.Available(s)&&world.Safe(s)).OrderBy(s=>(s.approach-at).sqrMagnitude).FirstOrDefault();Check(source!=null&&worker.TryBegin(source),"No standing wood task");for(int i=0;i<2400&&worker.Current!=VillagerResourceGathering.Phase.Harvest;i++){test.Hybrid.time+=.05f;worker.Tick(.05f,false);}Check(worker.Current==VillagerResourceGathering.Phase.Harvest,"Worker did not reach tree");StageGod();worker.GetComponent<CreatureAffordance>().cooldown=0;for(int i=0;i<200&&worker.Current==VillagerResourceGathering.Phase.Harvest;i++){test.Hybrid.time+=.05f;worker.Tick(.05f,false);}Check(worker.Current==VillagerResourceGathering.Phase.OfferWood,"Lone cutter did not offer to visible creature");for(int i=0;i<42;i++){test.Hybrid.time+=.05f;worker.Tick(.05f,false);}Check(worker.CanOfferCreatureTimber(god),"Stalled offer not feasible");}
  void Tick(){god.Tick(.05f);if(worker.Active)worker.Tick(.05f,test.paused);}
  try{
   god.Interrupt("Creature timber QA");foreach(var a in actors){a.Cancel();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();a.GetComponent<VillagerSocial>().ResetTask();slice.GetComponentInChildren<VillageFamilies>()?.Release(a.GetComponent<VillagerRoutine>());slice.GetComponentInChildren<VillageCathedral>()?.Cancel(a.GetComponent<VillagerRoutine>());a.GetComponent<CarryItem>().held=false;}
   test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100};test.resources=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(world.State));test.Resources.wood=8;test.Resources.resin=4;test.Resources.wheat=20;test.Resources.exposedWheat=test.Resources.freshFood=0;for(int i=0;i<3;i++)test.Tools.Practice(0,1);Check(test.Tools.OfferDelivery(test.Resources,0,2,VillageTool.BoundAxe,0,Vector3.zero)&&test.Tools.ReceiveDelivery(test.Resources,ToolDeliverySource.Player),"Axe fixture failed");stateField.SetValue(slice,test);god.NewSeason();world.ResetWorld();foreach(var a in cooldowns.Keys)a.cooldown=100000;foreach(var idea in ideas)idea.gameObject.SetActive(false);slice.SetSanctuaryOpen(false);
   Harvest();float stock=test.Resources.wood;string sourceId=worker.Source.id;float remaining=test.Resources.Find(sourceId).remaining;test.Resources.wood=test.Resources.Limit(VillageResource.Wood);Check(!worker.CanOfferCreatureTimber(god),"Full stores accepted");test.Resources.wood=stock;worker.GetComponent<CarryItem>().held=true;Check(!worker.CanOfferCreatureTimber(god),"Held cutter offered cargo");worker.GetComponent<CarryItem>().held=false;
   blocker=new GameObject("QA creature help occluder",typeof(BoxCollider));var eye=god.transform.position+Vector3.up*nav.Scale*10;var end=worker.GetComponent<Collider>().bounds.center;blocker.transform.position=(eye+end)*.5f;blocker.GetComponent<BoxCollider>().size=Vector3.one*nav.Scale*8;Physics.SyncTransforms();Check(!worker.CanOfferCreatureTimber(god),"Hidden offer accepted");UnityEngine.Object.DestroyImmediate(blocker);blocker=null;Physics.SyncTransforms();
   god.Perceive();var candidates=(System.Collections.Generic.List<CreatureCandidate>)typeof(CreatureHybrid).GetField("candidates",F).GetValue(god);Check(candidates.Any(c=>c.timber&&c.action==CreatureAction.RespondToGuidance&&c.situation==CreatureSituation.HelpRequested),"No autonomous help candidate");for(int i=0;i<80&&!worker.CreatureTimberClaimed;i++)Tick();Check(worker.CreatureTimberClaimed&&god.Owner==CreatureHybrid.ActionOwner.Curiosity&&mind.Current==CreatureCuriosity.Phase.TimberAssist&&test.Hybrid.intention.source==EvidenceSource.Autonomous,"Coordinator did not autonomously choose helper motor");Check(!actors[1].TryTimberRelay()&&!worker.ClaimCreatureTimber(god),"Duplicate helper claimed cargo");for(int i=0;i<1800&&!worker.CreatureTimberTaken;i++)Tick();Check(worker.CreatureTimberTaken&&test.Resources.wood==stock&&test.Resources.cargo[2].amount==3,"No native take / premature stock");
   test.paused=true;string paused=JsonUtility.ToJson(test);god.Tick(5);worker.Tick(5,true);Check(paused==JsonUtility.ToJson(test),"Pause advanced assistance");test.paused=false;typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);god.Interrupt("Player picked up creature");Check(!worker.CreatureTimberClaimed&&!worker.CreatureTimberTaken&&test.Resources.cargo[2].amount==0&&test.Resources.Find(sourceId).remaining==remaining+3&&test.Resources.wood==stock&&!test.Hybrid.receipt.eligible&&test.timberRelay?.count!=1,"Interrupted creature haul lost wood or awarded success");
   typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)stateField.GetValue(slice);god.NewSeason();world.ResetWorld();test.developmentFocus=test.observeWithoutFoodWork=true;Check(test.Valid()&&test.Resources.cargo.All(c=>c.amount==0)&&test.Resources.Find(sourceId).remaining==remaining+3&&test.Resources.wood==stock&&test.timberRelay?.count!=1&&!test.Hybrid.receipt.eligible,"Pending native reload did not recover unstocked timber");
   Harvest();Check(god.Guide(GuidanceIntent.Help,worker.GetComponent<HybridTarget>()),"Second Help rejected");for(int i=0;i<2400&&test.timberRelay?.creature!=true;i++)Tick();var relay=test.timberRelay;Check(relay?.creature==true&&relay.cutter==2&&relay.carrier==-1&&relay.amount==3&&test.Resources.wood==stock+3&&!worker.CreatureTimberClaimed&&mind.Current==CreatureCuriosity.Phase.Rest,"Native help carry/deposit failed: "+mind.Current+" / "+god.Explanation+" worker="+worker.Current+" wood="+test.Resources.wood+" history="+string.Join("; ",god.Journal.Capture().Reverse().Take(9).Select(e=>e.kind+":"+e.reason)));Check(test.Tools.learners[2].axeUses==2&&test.Tools.delivery.proof.stored&&test.Tools.delivery.source==ToolDeliverySource.Player,"Felling/tool evidence attribution lost");Check(test.Hybrid.receipt.eligible&&test.Hybrid.receipt.action==CreatureAction.RespondToGuidance&&test.Hybrid.receipt.situation==CreatureSituation.HelpRequested&&!test.Hybrid.receipt.fetched,"No contextual help receipt");float afterStock=test.Resources.wood;Check(god.Feedback(true)&&!god.Feedback(true)&&!worker.StoreCreatureTimber(god)&&test.Resources.wood==afterStock,"Duplicated success/feedback");
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)stateField.GetValue(slice);god.NewSeason();world.ResetWorld();Check(test.Valid()&&test.timberRelay.creature&&test.timberRelay.amount==3&&test.Resources.wood==stock+3&&!worker.CreatureTimberClaimed,"Native save lost creature assistance");Debug.Log("BWVR_CREATURE_TIMBER_RUNTIME_PASS: native felling/stalled cue, visible utility candidate, optional Help, exclusive coordinator ownership, real approach/take/carry/deposit, pause, interrupted cargo recovery, exact stock, separate felling/creature attribution, one contextual feedback and native Save/Load");
  }finally{if(blocker!=null)UnityEngine.Object.DestroyImmediate(blocker);god.Interrupt("Creature timber QA complete");foreach(var a in actors)a.Cancel();stateField.SetValue(slice,original);god.NewSeason();world.ResetWorld();foreach(var pair in cooldowns)pair.Key.cooldown=pair.Value;for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(active[i]);god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();for(int i=0;i<actors.Length;i++){actors[i].GetComponent<CarryItem>().held=false;actors[i].transform.SetPositionAndRotation(positions[i],rotations[i]);actors[i].GetComponent<IslandNavigator>().ResetRoute();}Physics.SyncTransforms();}
 }
}
}
